            //         }
            //     }
            //
            // consolidation by market
            //
            //     {
            //         "error": [],
            //         "result": [
            //             {
            //                 "pair": "ETHUSDT",
            //                 "positions": "1",
            //                 "type": "buy",
            //                 "leverage": "2.00000",
            //                 "cost": "28.49800",
